import { openRoamSession } from "/Users/trang.doan/Desktop/code/discourse-graph/.claude/worktrees/eng-2367-scroll-to-a-candidate-result-in-context-of-its-page-in-the/apps/roam/scripts/playwright/roamSession";

const main = async () => {
  const s = await openRoamSession({
    slot: "1",
    profileDir: "/Users/trang.doan/Desktop/code/discourse-graph/local/roam-playwright/profiles/playwright-1",
  });
  try {
    const out = await s.page.evaluate(async () => {
      const api = (window as any).roamAlphaAPI;
      const q = (s: string) => api.data.fast.q(s);
      // page containing a collapsed block that has a grandchild
      const collapsed = q(`[:find ?pu ?cu ?gu :where [?c :block/open false] [?c :block/uid ?cu] [?c :block/children ?g] [?g :block/uid ?gu] [?c :block/page ?p] [?p :block/uid ?pu]]`).slice(0, 1);
      const embeds = q(`[:find ?pu ?bu ?s :where [?b :block/string ?s] [(clojure.string/includes? ?s "{{embed")] [?b :block/uid ?bu] [?b :block/page ?p] [?p :block/uid ?pu]]`).slice(0, 1);
      const refs = q(`[:find ?pu ?bu ?s :where [?b :block/string ?s] [(clojure.string/includes? ?s "((")] [?b :block/uid ?bu] [?b :block/page ?p] [?p :block/uid ?pu]]`).slice(0, 1);
      const bigPages = q(`[:find ?pu (count ?b) :where [?b :block/page ?p] [?p :block/uid ?pu]]`).sort((a: any, b: any) => b[1] - a[1]).slice(0, 1);
      const res: any = { collapsed, embeds, refs, bigPages };
      const render = async (pageUid: string) => {
        const host = document.createElement("div");
        host.style.cssText = "position:fixed;top:0;left:0;width:600px;height:400px;overflow:auto;z-index:99999;background:white";
        const el = document.createElement("div");
        host.appendChild(el);
        document.body.appendChild(host);
        const before = performance.now();
        const ret = await api.ui.components.renderPage({ uid: pageUid, el, "hide-mentions?": true });
        const countAtResolve = el.querySelectorAll(".rm-block").length;
        await new Promise((r) => setTimeout(r, 1500));
        return { host, el, ret, countAtResolve, ms: performance.now() - before };
      };
      const describe = (el: Element) => Array.from(el.querySelectorAll(".rm-block")).slice(0, 4).map((b) => ({
        cls: b.className,
        attrs: Array.from(b.attributes).map((a) => a.name).join(","),
        dataBlockUid: b.getAttribute("data-block-uid"),
        inputId: b.querySelector(".rm-block__input")?.id,
      }));
      if (collapsed[0]) {
        const [pu, cu, gu] = collapsed[0];
        const r = await render(pu);
        res.collapsedProbe = {
          ret: r.ret, countAtResolve: r.countAtResolve,
          countLater: r.el.querySelectorAll(".rm-block").length,
          sample: describe(r.el),
          collapsedInDom: !!r.el.querySelector(`[id$="-${cu}"]`),
          grandchildInDom: !!r.el.querySelector(`[id$="-${gu}"]`),
          grandchildDataAttr: !!r.el.querySelector(`[data-block-uid="${gu}"]`),
          sameUidElsewhere: document.querySelectorAll(`[id$="-${cu}"]`).length,
          embedContainers: r.el.querySelectorAll(".rm-embed-container").length,
        };
        await api.ui.components.unmountNode({ el: r.el });
        res.collapsedProbe.afterUnmountChildren = r.el.childElementCount;
        r.host.remove();
      }
      for (const [key, row] of [["embedProbe", embeds[0]], ["refProbe", refs[0]]] as const) {
        if (!row) continue;
        const r = await render(row[0]);
        const container = r.el.querySelector(".rm-embed-container, .rm-block-ref");
        const b = r.el.querySelector(`[id$="-${row[1]}"]`)?.closest(".rm-block");
        res[key] = {
          string: String(row[2]).slice(0, 80),
          embedOuterSnippet: r.el.querySelector(".rm-embed-container")?.outerHTML.slice(0, 1200),
          blockRefSnippet: r.el.querySelector(".rm-block-ref")?.outerHTML.slice(0, 400),
          inputIds: Array.from(r.el.querySelectorAll(".rm-block__input")).map((x) => x.id).slice(0, 12),
          hostBlockAttrs: b ? Array.from(b.attributes).map((a) => `${a.name}=${a.value.slice(0, 60)}`) : null,
          had: !!container,
        };
        await api.ui.components.unmountNode({ el: r.el });
        r.host.remove();
      }
      if (bigPages[0]) {
        const r = await render(bigPages[0][0]);
        res.bigProbe = { total: bigPages[0][1], top: q(`[:find (count ?c) . :where [?p :block/uid "${bigPages[0][0]}"] [?p :block/children ?c]]`), countAtResolve: r.countAtResolve, countLater: r.el.querySelectorAll(".rm-block").length, placeholders: r.el.querySelectorAll(".rm-block--lazy, [class*=lazy], [class*=placeholder]").length };
        await api.ui.components.unmountNode({ el: r.el });
        r.host.remove();
      }
      return res;
    });
    console.log(JSON.stringify(out, null, 2));
  } finally {
    await s.close();
  }
};
main().catch((e) => { console.error(e.message); process.exit(1); });

